import { readFileSync } from "node:fs";
import process from "node:process";
import nativeCandidate from "./candidate-catalog.json";

// Generated by `node scripts/rearchitecture/update-catalog-candidate.mjs`. The native freshness
// test keeps ordinary web tests on that projection without requiring Cargo in the web job.
export function currentCandidate() {
  if (process.env.CATALOG_CANDIDATE) return JSON.parse(readFileSync(process.env.CATALOG_CANDIDATE, "utf8"));
  return structuredClone(nativeCandidate);
}
